ROOT=Path(__file__).parent
BG=ROOT/'renpy_project/game/images/bg'; CH=ROOT/'renpy_project/game/images/chars'; CG=ROOT/'renpy_project/game/images/cg'; WEB=ROOT/'assets/images'
for p in (BG,CH,CG,WEB): p.mkdir(parents=True,exist_ok=True)
# Original illustrated environments: layered gradients, architectural silhouettes, rain and light.
scenes={
'alley':('Callejón de los faroles','#10172d','#714b70','rain'),
'university':('Universidad Arco Norte','#18304b','#b88e79','campus'),
'police':('Comisaría central','#1d2639','#748398','office'),
'apartment':('Habitación 604','#1c1934','#745178','window'),
'tv':('Estudio Prisma','#211a3a','#b97886','studio'),
'rooftop':('Azotea del distrito','#1b2944','#bd7180','rooftop'),
'cafe':('Cafetería Nube','#263348','#d8a876','cafe'),
'interrogation':('Sala de interrogatorio 3','#151d31','#667993','room'),
}
def bg_svg(key,title,c1,c2,kind):
    extra=''
    if kind=='rain':
        extra='<path d="M0 500 L1280 460 1280 720 0 720Z" fill="#17182a"/><path d="M0 610 L1280 570" stroke="#b6c4df" opacity=".18" stroke-width="3"/><g opacity=".35" stroke="#a9bfe5" stroke-width="2">'+''.join(f'<path d="M{x} 80 l-55 130"/>' for x in range(50,1300,95))+'</g><g fill="#f2bd76">'+''.join(f'<circle cx="{x}" cy="{y}" r="{r}" opacity=".7"/>' for x,y,r in [(190,320,26),(480,265,14),(1020,350,34),(1160,210,11)])+'</g>'
    elif kind=='campus':
        extra='<path d="M0 520 L1280 500 1280 720 0 720Z" fill="#344454"/><path d="M120 275 L640 115 1160 275Z" fill="#28344c"/><rect x="170" y="275" width="940" height="280" fill="#425267"/><path d="M150 275h980" stroke="#dfb38c" stroke-width="10"/><g fill="#202b42">'+''.join(f'<rect x="{x}" y="{y}" width="105" height="110" rx="8"/>' for x in range(220,1080,180) for y in (325,445))+'</g><g fill="#f8d39b" opacity=".6">'+''.join(f'<rect x="{x}" y="{y}" width="88" height="90"/>' for x in range(228,1080,180) for y in (334,454))+'</g>'
    elif kind=='office':
        extra='<rect y="570" width="1280" height="150" fill="#252c3e"/><path d="M80 160h1120v430H80Z" fill="#27364c" stroke="#7c879d" stroke-width="5"/><g fill="#172437" stroke="#8391aa" stroke-width="4">'+''.join(f'<rect x="{x}" y="210" width="190" height="145"/>' for x in (125,350,575,800,1025))+'</g><g fill="#9eb2c7" opacity=".3">'+''.join(f'<path d="M{x} 215v135" stroke="#d5deeb" stroke-width="3"/>' for x in (220,445,670,895,1120))+'</g><rect x="420" y="460" width="440" height="175" rx="10" fill="#684d46"/><rect x="450" y="480" width="380" height="120" fill="#a16f57"/>'
    elif kind=='window':
        extra='<rect x="760" y="80" width="400" height="430" fill="#1c3150" stroke="#d0bed6" stroke-width="12"/><path d="M960 80v430M760 295h400" stroke="#d0bed6" stroke-width="8"/><g fill="#f5cb83">'+''.join(f'<rect x="{x}" y="{y}" width="18" height="34" opacity="{op}"/>' for x,y,op in [(800,150,.8),(900,190,.4),(1040,130,.65),(1090,355,.7),(825,365,.35)])+'</g><rect y="570" width="1280" height="150" fill="#271e35"/><path d="M160 580h420v20H160Z" fill="#bb8d71"/>'
    elif kind=='studio':
        extra='<rect y="560" width="1280" height="160" fill="#1a1830"/><path d="M110 100h1060v430H110Z" fill="#2a2344" stroke="#ed8ca2" stroke-width="5"/><g fill="#f08ba2" opacity=".75">'+''.join(f'<circle cx="{x}" cy="{y}" r="{r}"/>' for x,y,r in [(185,160,20),(1080,190,30),(250,460,13),(1030,420,17)])+'</g><path d="M370 520 Q640 410 910 520v60H370Z" fill="#68455d"/><rect x="470" y="365" width="340" height="140" rx="18" fill="#d67491"/>'
    elif kind=='rooftop':
        extra='<path d="M0 460h1280v260H0Z" fill="#20283d"/><path d="M0 300 L230 180 380 295 600 100 840 290 1010 160 1280 320v200H0Z" fill="#293954"/><g fill="#f8c783">'+''.join(f'<rect x="{x}" y="{y}" width="17" height="30" opacity=".72"/>' for x,y in [(100,360),(275,330),(425,380),(620,230),(700,290),(880,350),(1050,250),(1150,400)])+'</g><path d="M0 530h1280" stroke="#d18393" stroke-width="5" opacity=".65"/>'
    elif kind=='cafe':
        extra='<rect y="490" width="1280" height="230" fill="#62463f"/><path d="M95 105h1090v370H95Z" fill="#33485c"/><g stroke="#e1bd92" stroke-width="7">'+''.join(f'<path d="M{x} 110v360"/>' for x in (350,620,890))+'</g><g fill="#f6d69d" opacity=".55">'+''.join(f'<rect x="{x}" y="135" width="210" height="300"/>' for x in (120,375,645,915))+'</g><path d="M270 525h740v40H270Z" fill="#b27c5b"/><path d="M360 565v155m550-155v155" stroke="#49363c" stroke-width="24"/>'
    else:
        extra='<rect x="85" y="90" width="1110" height="540" rx="22" fill="#202a3f" stroke="#8190a7" stroke-width="6"/><rect x="180" y="180" width="920" height="315" fill="#10192a"/><circle cx="640" cy="335" r="120" fill="#687890" opacity=".12"/><rect x="520" y="565" width="240" height="35" fill="#b8c5d5"/><path d="M560 600v120m160-120v120" stroke="#9ca9bb" stroke-width="12"/>'
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720" viewBox="0 0 1280 720"><defs><linearGradient id="g" x2="0" y2="1"><stop stop-color="{c1}"/><stop offset="1" stop-color="{c2}"/></linearGradient><radialGradient id="glow"><stop stop-color="#f3bb91" stop-opacity=".42"/><stop offset="1" stop-color="#f3bb91" stop-opacity="0"/></radialGradient></defs><rect width="1280" height="720" fill="url(#g)"/><ellipse cx="690" cy="255" rx="540" ry="360" fill="url(#glow)"/>{extra}<path d="M0 700 Q300 665 650 700 T1280 690" stroke="#efd4c0" opacity=".12" fill="none" stroke-width="5"/><text x="45" y="65" fill="#fff" opacity=".18" font-family="sans-serif" font-size="20" letter-spacing="7">{title.upper()}</text></svg>'''
for name,(title,c1,c2,kind) in scenes.items():
    svg=bg_svg(name,title,c1,c2,kind)
    for dest in [BG/f'{name}.png',WEB/f'bg_{name}.png']:
        cairosvg.svg2png(bytestring=svg.encode(),write_to=str(dest),output_width=1280,output_height=720)

# Static anime-inspired portraits, transparent, expression variants are separate still files.
people={
'noa':('#202641','#293c69','#e9b08d','#15213b','#75d2e8','Noa'),
'iris':('#30344a','#152331','#f0c4a4','#202637','#afd7e7','Iris'),
'nera':('#211b35','#412645','#d9a38e','#171326','#de9dc2','Nera'),
'vela':('#d486a4','#8e456d','#f3c7ac','#49334d','#8ce3dc','Vela'),
'chief':('#303947','#5a463f','#dea98c','#252a36','#e9c58f','Ciro'),
}
expressions=['neutral','smile','tense','anger','fear','surprise','sad','suspicious']
def char_svg(name,palette,exp):
    hair,coat,skin,hair2,eye,label=palette
    mouth={'neutral':'M270 410 Q300 415 330 410','smile':'M268 405 Q300 440 334 405','tense':'M270 418 Q300 405 332 418','anger':'M270 414 Q300 394 334 414','fear':'M278 412 Q300 429 322 412','surprise':'M282 410 Q300 431 318 410','sad':'M270 426 Q300 395 334 426','suspicious':'M270 415 Q298 406 330 419'}[exp]
    brow={'neutral':'M220 288l58 6m42 0 58-6','smile':'M220 291l58 4m42 4 58-4','tense':'M220 305l58-14m42-2 58 16','anger':'M220 311l58-20m42 0 58 20','fear':'M220 278l58 10m42 0 58-10','surprise':'M220 270l58 8m42 0 58-8','sad':'M220 284l58 12m42-2 58-12','suspicious':'M220 300l58-9m42 2 58 9'}[exp]
    eyes='<ellipse cx="258" cy="338" rx="21" ry="27" fill="#fff"/><ellipse cx="342" cy="338" rx="21" ry="27" fill="#fff"/><ellipse cx="258" cy="342" rx="12" ry="18" fill="'+eye+'"/><ellipse cx="342" cy="342" rx="12" ry="18" fill="'+eye+'"/><circle cx="262" cy="338" r="5" fill="#fff"/><circle cx="346" cy="338" r="5" fill="#fff"/>'
    if name=='nera':
        hairshape='<path d="M176 340 Q135 90 300 62 Q490 75 430 360 L402 238 388 462 350 284 300 474 267 278 225 452 214 250Z" fill="'+hair+'" stroke="#131522" stroke-width="10"/><path d="M188 163Q300 72 420 166L383 210Q302 163 212 210Z" fill="'+hair2+'" opacity=".65"/>'
    elif name=='vela':
        hairshape='<path d="M177 340 Q145 100 300 65 Q455 90 423 360L400 236 385 420 355 277 317 441 275 274 230 425 214 245Z" fill="'+hair+'" stroke="#57344e" stroke-width="10"/><path d="M204 185Q290 70 395 180" fill="none" stroke="#ffd4e5" stroke-width="16" opacity=".8"/>'
    else:
        hairshape='<path d="M176 340 Q145 91 300 61 Q455 73 424 355 L400 236 383 439 350 277 315 452 275 270 230 421 214 245Z" fill="'+hair+'" stroke="#111827" stroke-width="10"/><path d="M193 196Q260 99 385 152" fill="none" stroke="'+hair2+'" stroke-width="13" opacity=".75"/>'
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="600" height="900" viewBox="0 0 600 900"><g stroke-linejoin="round"><path d="M65 900Q90 605 215 555L300 525 385 555Q520 610 545 900Z" fill="{coat}" stroke="#111725" stroke-width="12"/><path d="M230 570l70 145 70-145-70-48Z" fill="#eee3db"/><path d="M266 640l34 45 34-45-34-48Z" fill="#d88d9c"/><path d="M235 192Q300 132 365 192V402Q365 470 300 480Q235 470 235 402Z" fill="{skin}" stroke="#201c2b" stroke-width="9"/><path d="M229 380Q192 343 207 280M370 380Q407 343 392 280" fill="none" stroke="#201c2b" stroke-width="11"/>{hairshape}<path d="{brow}" stroke="#3b2932" stroke-width="9" stroke-linecap="round" fill="none"/>{eyes}<path d="M300 346l-9 37 15 2" stroke="#b87972" stroke-width="5" fill="none"/><path d="{mouth}" stroke="#8c4c58" stroke-width="6" fill="none" stroke-linecap="round"/><path d="M204 392Q220 496 300 510Q380 496 396 392V435Q380 515 300 528Q220 515 204 435Z" fill="{hair}" opacity=".96"/><path d="M225 278Q250 250 277 270M323 270Q355 246 380 276" fill="none" stroke="{hair}" stroke-width="25" stroke-linecap="round"/><path d="M244 355q-9 7-18 0m149 0q-9 7-18 0" stroke="#bf7277" stroke-width="4" opacity=".55"/></g><text x="300" y="860" text-anchor="middle" fill="#ffffff" opacity=".55" font-family="sans-serif" font-size="18" letter-spacing="6">{label.upper()} · {exp.upper()}</text></svg>'''
for name,palette in people.items():
    for exp in expressions:
        svg=char_svg(name,palette,exp)
        for dest in [CH/f'{name}_{exp}.png',WEB/f'{name}_{exp}.png']:
            cairosvg.svg2png(bytestring=svg.encode(),write_to=str(dest),output_width=600,output_height=900)
# Key still CGs: stylized composite panels with character-shaped silhouette implied by moonlit profile.
for key,bgname,caption,accent in [('discovery','alley','LA PRIMERA PÁGINA','#edc784'),('revelation','rooftop','EL NOMBRE QUE FALTA','#d68ea4'),('lastpage','apartment','NINGUNA TINTA ES ETERNA','#80d7d1')]:
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720"><image href="../bg/{bgname}.png" width="1280" height="720"/><rect width="1280" height="720" fill="#101421" opacity=".27"/><path d="M655 720Q675 450 780 370Q732 218 844 135Q958 65 1040 182Q1102 276 1040 377Q1170 440 1208 720Z" fill="#121728" stroke="{accent}" stroke-opacity=".6" stroke-width="5"/><path d="M785 328Q850 247 961 304" fill="none" stroke="{accent}" stroke-width="6" opacity=".75"/><rect x="90" y="500" width="490" height="5" fill="{accent}" opacity=".8"/><text x="90" y="570" font-family="sans-serif" font-size="22" letter-spacing="8" fill="{accent}">CHRONICLE OF ASH</text><text x="90" y="625" font-family="sans-serif" font-size="40" letter-spacing="6" fill="#fff">{caption}</text></svg>'''
    # Replace relative external image with embedded data URI.
    source=(BG/f'{bgname}.png').read_bytes(); import base64
    uri='data:image/png;base64,'+base64.b64encode(source).decode()
    svg=svg.replace(f'../bg/{bgname}.png',uri)
    cairosvg.svg2png(bytestring=svg.encode(),write_to=str(CG/f'{key}.png'),output_width=1280,output_height=720)
    cairosvg.svg2png(bytestring=svg.encode(),write_to=str(WEB/f'cg_{key}.png'),output_width=1280,output_height=720)
print('Art generated: 8 backgrounds, 40 static expressions, 3 CGs')

/* Chronicle of Ash — interactive, original visual novel. localStorage save; no external game engine required. */
(()=>{'use strict';
const $=s=>document.querySelector(s), stage=$('#stage'), line=$('#line'), speaker=$('#speaker'), portrait=$('#portrait'), portraitWrap=$('#portrait-wrap'), choicesBox=$('#choices'), modal=$('#modal'), toast=$('#toast');
const img={bg:n=>`assets/images/bg_${n}.png`,char:(n,e='neutral')=>`assets/images/${n}_${e}.png`,cg:n=>`assets/images/cg_${n}.png`};
const state={chapter:1,scene:0,path:'undecided',suspicion:12,police:38,devotion:18,fear:12,sanity:82,power:55,evidence:0,rel:{Iris:0,Nera:0,Vela:0,Ciro:0},flags:{face:false,real:false,witness:false,mistakes:0},name:'',cause:'',hour:'',clues:[],endings:[],history:[],ngp:false};
const clamp=()=>{for(const k of ['suspicion','police','devotion','fear','sanity','power'])state[k]=Math.max(0,Math.min(100,state[k]));state.evidence=Math.max(0,Math.min(10,state.evidence))};
const inc=(k,n)=>{state[k]+=n;clamp()},rel=(k,n)=>{state.rel[k]+=n},clue=s=>{if(!state.clues.includes(s))state.clues.push(s)};
function scene(bg,title='LA CIUDAD DE CENIZA',chapter='CAPÍTULO 1 · EL MARGEN DE LA NOCHE'){stage.style.backgroundImage=`url('${img.bg(bg)}')`;$('#scene-title').textContent=title;$('#chapter-label').textContent=chapter;portraitWrap.style.opacity='1';$('#cg')?.remove()}
function showCG(name){$('#cg')?.remove();const el=document.createElement('img');el.id='cg';el.className='cg';el.src=img.cg(name);stage.append(el)}
function say(who,text,person=null,expression='neutral',next=null){choicesBox.hidden=true;portraitWrap.style.display=person?'flex':'none';if(person){portrait.src=img.char(person,expression);portrait.alt=`${who}, expresión ${expression}`}speaker.textContent=who;line.textContent=text;$('#advance').style.display=next?'block':'none';$('#advance').onclick=()=>next&&next()}
function choose(items){$('#advance').style.display='none';choicesBox.innerHTML='';choicesBox.hidden=false;for(const [label,fn] of items){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{choicesBox.hidden=true;fn()};choicesBox.append(b)}}
function notify(text){toast.textContent=text;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2100)}
function sequence(arr,done){let i=0;const go=()=>{if(i>=arr.length){done?.();return}const s=arr[i++];if(s.cg)showCG(s.cg);if(s.bg)scene(s.bg,s.title,s.chapter);say(s.who,s.text,s.person,s.exp||'neutral',go)};go()}
function title(){scene('alley','CHRONICLE OF ASH','NOVELA VISUAL · MISTERIO SOBRENATURAL');portraitWrap.style.display='none';$('#advance').style.display='none';$('#speaker').textContent='';$('#line').textContent='';choicesBox.hidden=true;$('#cg')?.remove();const card=document.createElement('div');card.className='title-card';card.innerHTML='<div><p>UNA CIUDAD · QUINCE FINALES</p><h1>Chronicle<br>of Ash</h1><p>LA CIUDAD DE CENIZA</p><button>Comenzar historia</button></div>';stage.append(card);card.querySelector('button').onclick=()=>{card.remove();begin()}}
function begin(){state.scene=0;scene('alley');sequence([{cg:'discovery',who:'Narración',text:'La lluvia dejó el callejón sin testigos. Casi sin testigos.'},{who:'Noa Senda',person:'noa',exp:'tense',text:'No estaba aquí cuando salí de la universidad. Tiene mi nombre escrito en la tapa… aunque la letra no es mía.'},{who:'Narración',text:'El cuaderno negro está seco. En la primera hoja, una frase: «Lo que se entrega a la noche siempre cobra una respuesta».'},{who:'Noa Senda',person:'noa',exp:'suspicious',text:'¿Quién dejaría algo así en un callejón?'}],()=>choose([
['Llevarlo a la comisaría y declarar dónde apareció',()=>{state.path='detective';inc('police',12);inc('suspicion',-5);rel('Ciro',1);clue('Cuaderno hallado en el callejón; origen incierto');apartment()}],
['Guardarlo y estudiar primero las páginas',()=>{state.path='kira';inc('devotion',8);inc('sanity',-3);clue('Tapa sin huellas legibles bajo la lluvia');apartment()}],
['No tocarlo; buscar cámaras y preguntar al quiosquero',()=>{state.path='ally';inc('evidence',1);inc('police',5);inc('suspicion',-3);state.flags.witness=true;clue('Un quiosquero vio una silueta dejar el cuaderno');apartment()}]
]))}
function apartment(){scene('apartment');sequence([{who:'Nera',person:'nera',text:'Buenas. ¿Tienes una manzana? No, claro que no. La gente cree que los muertos necesitan modales.'},{who:'Noa Senda',person:'noa',exp:'surprise',text:'¿Quién eres? ¿Cómo has entrado?'},{who:'Nera',person:'nera',text:'Nera. Vigía de la última tinta. Y sí, ese cuaderno puede escribir una muerte. Nombre auténtico y rostro conocido. Nada de apodos.'},{who:'Narración',text:'Nera bosteza y se sienta en el suelo, como si anunciar lo imposible fuera una tarea doméstica.'}],()=>choose([
['Pedir las reglas completas, sin aceptar nada',()=>{inc('sanity',4);rel('Nera',1);clue('Regla declarada: nombre auténtico + rostro reconocido');say('Nera','Causa y hora son opcionales; el efecto no puede superar lo posible. Un nombre equivocado no hace nada.','nera','neutral',broadcast)}],
['Exigir que se marche y cerrar el cuaderno',()=>{inc('sanity',2);inc('power',-4);rel('Nera',-1);say('Nera','Qué falta de hospitalidad. Te lo explicaré desde el pasillo.','nera','suspicious',broadcast)}],
['Preguntar qué gana ella',()=>{inc('suspicion',3);rel('Nera',2);say('Nera','Yo gano una manzana. La eternidad es larga y la fruta siempre está demasiado lejos.','nera','smile',broadcast)}]
]))}
function broadcast(){scene('tv');sequence([{who:'Radio Ciudad',text:'La ciudad debate la muerte de tres criminales condenados. En redes, una firma anónima ya tiene nombre: Kira. La policía no confirma relación entre los casos.'},{who:'Narración',text:'El presentador no mostró imágenes explícitas; sí mostró portadas, horarios y el miedo creciendo en comentarios.'},{who:'Noa Senda',person:'noa',exp:'tense',text:'Si alguien usa el cuaderno, ¿la ciudad lo llamará justicia?'}],()=>choose([
['La opinión pública no convierte sospechas en pruebas',()=>{inc('suspicion',-2);inc('police',4);clue('Las tres muertes compartían cobertura mediática, no causa confirmada');university()}],
['La gente puede apoyar una idea y temer a quien la encarna',()=>{inc('devotion',6);inc('fear',3);rel('Vela',1);university()}],
['Desconectar la pantalla',()=>{inc('sanity',3);inc('fear',1);university()}]
]))}
function university(){scene('university');sequence([{who:'Iris Vale',person:'iris',exp:'suspicious',text:'Soy Iris Vale. Asesoro al equipo de investigación. ¿Por qué una estudiante de criminología preguntó por los horarios de los fallecimientos?'},{who:'Noa Senda',person:'noa',text:'Porque los horarios son públicos y no prueban nada por sí solos.'},{who:'Iris Vale',person:'iris',exp:'neutral',text:'Buena respuesta. ¿Y cuál es tu hipótesis que más te incomoda?'}],()=>choose([
['Un imitador puede estar copiando el patrón de los medios',()=>{inc('evidence',1);rel('Iris',1);inc('police',3);clue('Hipótesis de imitación mediática; requiere contraste');say('Iris Vale','Es comprobable. No significa que sea cierta.','iris','smile',cafe)}],
['Que la investigación confirme primero cronología y coartadas',()=>{inc('evidence',2);rel('Iris',2);inc('suspicion',-2);clue('Cronología verificada; faltan coartadas independientes');say('Iris Vale','Exacto. Una coartada se comprueba; no se adivina.','iris','smile',cafe)}],
['Que la propia policía filtre información sin querer',()=>{inc('suspicion',4);inc('police',-3);clue('Posible filtración institucional aún no corroborada');say('Iris Vale','Esa hipótesis también se investiga con registros, no con intuición.','iris','tense',cafe)}]
]))}
function cafe(){scene('cafe');sequence([{who:'Vela Lune',person:'vela',exp:'smile',text:'Noa, ¿verdad? Soy Vela. Yo creo que la ciudad merece menos impunidad. No significa que confíe en cualquier desconocido.'}],()=>choose([
['Escuchar su motivo sin prometer lealtad',()=>{rel('Vela',2);inc('devotion',2);say('Vela Lune','Gracias. La gente oye una canción y se inventa una persona detrás.','vela','smile',police)}],
['Discrepar: el miedo no es justicia',()=>{rel('Vela',-1);inc('police',2);inc('fear',-2);say('Vela Lune','Puede que tengas razón. No me gusta que la respuesta sea tan sencilla.','vela','sad',police)}],
['Preguntar qué fuentes tiene, no qué siente',()=>{inc('evidence',1);rel('Vela',1);clue('Vela solo conoce rumores públicos; no es testigo de los casos');say('Vela Lune','Ninguna fuente privada. No confundas mi fama con acceso a la verdad.','vela','neutral',police)}]
]))}
function police(){scene('police');sequence([{who:'Ciro Senda',person:'chief',text:'El detective extranjero usa el nombre Iris Vale. Es brillante, excéntrica y detesta las afirmaciones que no puede verificar.'},{who:'Ciro Senda',person:'chief',exp:'tense',text:'Noa, si viste algo en ese callejón, dilo. La confianza sirve cuando también admite dudas.'}],()=>choose([
['Entregar el cuaderno y contar toda la verdad',()=>{state.path='detective';inc('police',12);inc('suspicion',-4);inc('evidence',1);rel('Ciro',2);clue('Declaración íntegra de Noa registrada');chapterClose('Ciro no dijo que el objeto fuera inofensivo. Lo puso bajo custodia y llamó a dos testigos.') }],
['Ocultar el cuaderno, pero ofrecer ayudar con las pistas',()=>{state.path='ally';inc('police',3);inc('suspicion',3);rel('Ciro',-1);chapterClose('La omisión pesó más que la mentira: Noa no podía olvidar que había elegido callar.') }],
['Negarlo todo y pedir que dejen a la familia fuera',()=>{state.path='kira';inc('police',-8);inc('suspicion',8);inc('sanity',-4);state.flags.mistakes++;chapterClose('Ciro no levantó la voz. Su silencio hizo más daño que una acusación.') }]
]))}
function chapterClose(aside){clamp();sequence([{bg:'rooftop',who:'Iris Vale',person:'iris',exp:'tense',text:'Las páginas públicas no bastan para atribuir un patrón a una persona. Tendremos que separar hechos, fuentes y coincidencias.'},{who:'Narración',text:`${aside} La lluvia se alejó. En las pantallas de la ciudad, el nombre Kira seguía creciendo sin que nadie pudiera probar quién lo había escrito.`}],()=>{$('#chapter-label').textContent='CAPÍTULO 1 · COMPLETADO';say('','Capítulo 1 · El margen de la noche. Pulsa continuar para elegir tu ruta.');$('#advance').onclick=chapterTwo})}
function chapterTwo(){scene('interrogation','RUTAS · CAPÍTULO 2','CAPÍTULO 2 · ELEGIR SIN CERTEZAS');say('Iris Vale',`Ruta inicial: ${state.path}. Evidencia: ${state.evidence}. Confianza policial: ${state.police}. ¿Qué haces ahora?`,'iris','neutral',()=>choose([
['Ruta detective: auditar horarios, fuentes y coartadas',()=>{state.path='detective';routeDetective()}],['Ruta aliada: colaborar sin entregar todas tus dudas',()=>{state.path='ally';routeAlly()}],['Ruta Kira: usar el poder en una decisión de alto riesgo',()=>{state.path='kira';routeKira()}],['Ruta mártir: cortar la cadena exponiéndote',()=>{state.path='martyr';inc('sanity',-8);finish()}],['Ruta traidor: vender información a Nera por manzanas',()=>{state.path='traitor';rel('Nera',3);finish()}],['Renunciar al cuaderno y entregarlo',()=>{state.path='renounce';state.power=0;state.flags.face=false;finish()}]
]))}
function routeDetective(){scene('police','MÉTODO · PRUEBAS','CAPÍTULO 2 · RUTA DETECTIVE');say('Iris Vale','La vigilancia solo se autoriza con hechos y alcance limitado. Podemos revisar el registro público de cámaras, entrevistar testigos o comparar coartadas.','iris','suspicious',()=>choose([
['Verificar dos fuentes independientes y preservar el registro',()=>{inc('evidence',4);inc('police',12);inc('suspicion',-7);rel('Iris',2);clue('Dos fuentes independientes corroboran la cronología');detectiveSecond()}],
['Cotejar coartadas y descartar una coincidencia',()=>{inc('evidence',3);inc('police',7);inc('suspicion',-5);rel('Iris',1);clue('Coartada comprobada mediante registro público');detectiveSecond()}],
['Filtrar una sospecha sin verificar para acelerar el caso',()=>{inc('evidence',-2);inc('police',-15);inc('suspicion',18);inc('sanity',-5);detectiveSecond('El rumor llevó a un testigo inocente a abandonar la ciudad. La pista quedó contaminada.')}]
]))}
function detectiveSecond(note=''){if(note)notify(note);choose([
['Construir una conclusión que sobreviva a una refutación',()=>{inc('evidence',2);inc('police',7);inc('suspicion',-4);rel('Iris',1);finish()}],
['Proteger a un informante aunque el informe quede incompleto',()=>{inc('evidence',1);inc('police',2);rel('Ciro',2);finish()}],
['Revisar el tablón de pistas y decidir',()=>{board();inc('evidence',1);finish()}]
])}
function routeAlly(){scene('cafe','ALIANZAS · CONFIANZA','CAPÍTULO 2 · RUTA ALIADA');say('Vela Lune','Puedo poner mi plataforma al servicio de una corrección pública. Iris puede compartir el método, no sus expedientes. ¿A quién priorizamos?','vela','neutral',()=>choose([
['Compartir incertidumbre con Iris y contrastar el registro',()=>{rel('Iris',3);inc('police',12);inc('evidence',2);inc('suspicion',-4);finish()}],
['Ayudar a Vela a separar admiración de obediencia',()=>{rel('Vela',3);inc('devotion',12);inc('fear',-7);finish()}],
['Proteger a Ciro del escándalo y aportar una pista',()=>{rel('Ciro',2);inc('police',6);inc('evidence',4);finish()}],
['Abrir el cuaderno y fingir que fue un accidente',()=>{state.path='kira';state.flags.mistakes++;inc('sanity',-15);routeKira()}]
]))}
function routeKira(){scene('apartment','LA PÁGINA EN BLANCO','CAPÍTULO 2 · RUTA DEL CUADERNO');say('Nera','Las reglas no son una recomendación. Y una página no demuestra nada sobre una persona real. No uses nombres de gente real: esto es un drama ficticio.','nera','suspicious',()=>choose([
['Anotar en la página de prueba un alias inventado, no una persona',()=>{state.flags.real=true;state.flags.face=true;state.name='Rival ficticio: Eco';state.cause='Silencio';state.hour='03:00';inc('sanity',-5);inc('devotion',14);notebook(true);}],
['Destruir tu copia de la llave y no volver a escribir',()=>{state.path='renounce';state.power=0;finish()}],
['Preguntar a Nera si el poder tiene un límite',()=>{rel('Nera',2);inc('power',-3);say('Nera','Sí. La voluntad no puede torcer lo físicamente imposible. Tampoco puede volver inocente una decisión.','nera','neutral',()=>kiraSecond())}]
]))}
function kiraSecond(){choose([
['Mantener la calma y dejar de buscar aprobación',()=>{inc('sanity',6);inc('devotion',4);inc('fear',-3);finish()}],
['Usar el cuaderno otra vez: la doble entrada revela tu patrón',()=>{state.flags.mistakes++;inc('power',-12);inc('sanity',-15);inc('fear',18);inc('suspicion',8);finish()}],
['Provocar pánico para forzar una respuesta pública',()=>{inc('fear',38);inc('devotion',8);inc('sanity',-8);finish()}]
])}
function notebook(fromRoute=false){modal.hidden=false;modal.innerHTML=`<button class="close" onclick="window.closePanel()">Cerrar ✕</button><h2>Cuaderno de ceniza</h2><p><strong>Regla 01</strong> · Nombre auténtico y rostro reconocido son necesarios.<br>Un nombre falso no activa la página. Este relato solo contiene identidades inventadas.</p><label>Nombre (ficción)</label><input id="nb-name" maxlength="36" value="${esc(state.name)}" placeholder="Ej.: Eco, personaje ficticio"><label>Causa (opcional)</label><input id="nb-cause" maxlength="36" value="${esc(state.cause)}" placeholder="Opcional"><label>Hora (opcional)</label><input id="nb-hour" maxlength="10" value="${esc(state.hour)}" placeholder="Opcional"><p>Rostro reconocido: <strong>${state.flags.face?'SÍ':'NO'}</strong> · Poder: ${state.power}</p><p id="nb-error" style="color:#e69c9c"></p><button id="nb-write">Confirmar entrada ficticia</button> <button id="nb-cancel">Cerrar sin escribir</button>`;$('#nb-write').onclick=()=>{const name=$('#nb-name').value.trim();if(!state.flags.real||!state.flags.face||!name){state.flags.mistakes++;$('#nb-error').textContent='Bloqueado: falta nombre confirmado y/o rostro conocido.';return}state.name=name;state.cause=$('#nb-cause').value;state.hour=$('#nb-hour').value;state.flags.mistakes++;inc('power',-7);inc('sanity',-9);inc('fear',4);clue('Una entrada ficticia comprobada por el sistema');closePanel();notify('Ensayo narrativo ficticio registrado.')};$('#nb-cancel').onclick=()=>{closePanel();kiraSecond()}}
function finish(){clamp();const id=endingId();if(!state.endings.includes(id))state.endings.push(id);save(false);const titles={E01:'Archivo de la verdad',E02:'Sombra útil',E03:'La verdad incompleta',E04:'Dos métodos, una promesa',E05:'Fuera del altar',E06:'La alianza incómoda',E07:'La puerta entreabierta',E08:'La quietud prestada',E09:'Caso sin prueba',E10:'La firma del error',E11:'La tinta interior',E12:'Ciudad bajo cristal',E13:'El precio de una siesta',E14:'La última hoja',E15:'No escribir'};const texts={E01:['Iris Vale','La cadena de pruebas se sostiene. No porque confiáramos ciegamente: cada dato sobrevivió a una comprobación.'],E02:['Iris Vale','La ciudad conocerá la verdad. Mi nombre no aparecerá en el informe.'],E03:['Iris Vale','Llegamos tarde para reparar el daño. Aun así, el cuaderno ya no decidirá el próximo caso.'],E04:['Iris Vale','Gracias por compartir tus dudas antes de convertirlas en certezas.'],E05:['Vela Lune','No te pediré que adores a nadie. Quiero que me escuches a mí.'],E06:['Ciro Senda','Entregaremos la evidencia completa. Sin escoger qué parte merece existir.'],E07:['Nera','Pensaste que ayudar era lo mismo que obedecer. Ahora ya sabes la diferencia.'],E08:['Noa Senda','El miedo tenía una fecha de caducidad. Yo no quise leerla.'],E09:['Iris Vale','Tu sospecha no produjo una sola prueba verificable. No es lo mismo que resolver el caso.'],E10:['Noa Senda','Me equivoqué al creer que una página podía ocultar todas mis huellas.'],E11:['Noa Senda','Ya no sé si estoy escribiendo para cambiar el mundo o para acallar mi propia cabeza.'],E12:['Iris Vale','El miedo no es consentimiento. La ciudad te teme, pero no te pertenece.'],E13:['Nera','Una manzana por la información. No, no acepto pagos en efectivo.'],E14:['Noa Senda','Que el final de mi historia impida el principio de otra.'],E15:['Noa Senda','Cerré el cuaderno. Nera sigue exigiendo alquiler por vivir en mi armario.']};const [who,text]=texts[id];scene('rooftop',`FINAL ${id} · ${titles[id].toUpperCase()}`,'ARCHIVO · 15 FINALES');showCG(id==='E14'?'lastpage':id==='E01'?'revelation':'lastpage');say(who,text,({ 'Iris Vale':'iris','Vela Lune':'vela','Ciro Senda':'chief','Nera':'nera','Noa Senda':'noa'})[who],'sad',()=>{portraitWrap.style.display='none';line.innerHTML=`<div class="ending">${id} · ${titles[id]}</div><p>${endingEpilogue(id)}</p><p>Finales descubiertos: ${state.endings.length} / 15</p><button onclick="window.archive()">Galería / archivo</button> <button onclick="window.newRoute()">Nueva ruta</button> <button onclick="window.restart()">Menú / reiniciar</button>`;$('#advance').style.display='none';$('#speaker').textContent='FIN DE RUTA';if(!state.endings.includes(id))state.endings.push(id);state.ngp=true;save(false)})}
function endingEpilogue(id){return {E01:'La verdad no devuelve a nadie, pero evita que el siguiente caso se pierda.',E02:'Una victoria sin aplausos, y sin certezas cómodas.',E03:'La justicia sobrevivió; la confianza, no.',E04:'La investigación y la amistad siguieron rutas paralelas, por fin con el mismo destino.',E05:'La devoción se transformó en una conversación imperfecta, pero humana.',E06:'Una alianza incómoda cerró el caso sin borrar las preguntas.',E07:'Te apartaste del tablero antes de que alguien más moviera tu pieza.',E08:'La ciudad se acostumbró a la calma; nadie se puso de acuerdo sobre su precio.',E09:'El detective se marchó con una pregunta más y una respuesta menos.',E10:'Dos errores públicos bastaron para que la investigación encontrara un patrón.',E11:'El cuaderno quedó cerrado. La habitación, no.',E12:'La falsa paz se agrietó desde dentro.',E13:'Traicionaste a ambos bandos; el único beneficiario pidió una siesta.',E14:'Tu sacrificio puso fin al vínculo, no a todas las dudas.',E15:'Nera aceptó una manzana como depósito. La humanidad conservó una deuda absurda.'}[id]}
function endingId(){if(state.path==='renounce')return'E15';if(state.path==='martyr')return'E14';if(state.path==='traitor')return'E13';if(state.path==='detective'){if(state.evidence>=6&&state.police>=65)return'E01';if(state.evidence>=4&&state.suspicion<45)return'E02';if(state.evidence<2)return'E09';return'E03'}if(state.path==='ally'){if(state.rel.Iris>=3&&state.police>=55)return'E04';if(state.rel.Vela>=3&&state.devotion>=55)return'E05';if(state.evidence>=4)return'E06';return'E07'}if(state.path==='kira'){if(state.flags.mistakes>=2)return'E10';if(state.sanity<25)return'E11';if(state.devotion>=75&&state.fear<60)return'E08';if(state.fear>=70)return'E12';return'E08'}return'E15'}
function metrics(){const names=['Sospecha del detective','Confianza policial','Devoción a Kira','Miedo público','Cordura','Poder del cuaderno'];const vals=[state.suspicion,state.police,state.devotion,state.fear,state.sanity,state.power];return names.map((n,i)=>`<p>${n} · ${vals[i]}<div class="meter"><i style="width:${vals[i]}%"></i></div></p>`).join('')+`<p>Evidencia: ${state.evidence}/10</p><p>Relaciones: Iris ${state.rel.Iris} · Nera ${state.rel.Nera} · Vela ${state.rel.Vela} · Ciro ${state.rel.Ciro}</p>`}
function board(){modal.hidden=false;modal.innerHTML=`<button class="close" onclick="window.closePanel()">Cerrar ✕</button><h2>Tablón · Hechos comprobables</h2><p>Hipótesis no equivalen a prueba: muertes nocturnas · informativos públicos · sesgo de selección.</p><div class="board">${state.clues.length?state.clues.map(c=>`<div class="clue">${esc(c)}</div>`).join(''):'<p>Ninguna pista confirmada aún.</p>'}</div><p>Evidencia ${state.evidence}/10 · Testigo: ${state.flags.witness?'sí':'no'} · Vigilancia: ${state.evidence>=3?'autorizable con alcance limitado':'sin base suficiente'}</p>`}
function archive(){modal.hidden=false;const all=['E01','E02','E03','E04','E05','E06','E07','E08','E09','E10','E11','E12','E13','E14','E15'];modal.innerHTML=`<button class="close" onclick="window.closePanel()">Cerrar ✕</button><h2>Archivo · Galería y finales</h2><p>${state.endings.length}/15 finales descubiertos · New Game+ ${state.ngp?'desbloqueado':'bloqueado (termina una ruta)'}</p><div class="archive">${all.map((id,i)=>`<figure>${state.endings.includes(id)?`<img src="${img.cg(i%2?'lastpage':'revelation')}" alt="CG desbloqueado">`:'<div class="clue" style="height:120px;display:grid;place-items:center">???</div>'}<figcaption>${state.endings.includes(id)?id+' · '+({E01:'Archivo de la verdad',E02:'Sombra útil',E03:'La verdad incompleta',E04:'Dos métodos, una promesa',E05:'Fuera del altar',E06:'La alianza incómoda',E07:'La puerta entreabierta',E08:'La quietud prestada',E09:'Caso sin prueba',E10:'La firma del error',E11:'La tinta interior',E12:'Ciudad bajo cristal',E13:'El precio de una siesta',E14:'La última hoja',E15:'No escribir'}[id]):'Final oculto'}</figcaption></figure>`).join('')}</div><h2>Logros</h2><p>${state.endings.length?'Primera ceniza · Has alcanzado un final.':''} ${state.endings.length>=5?'Cinco desenlaces · La verdad admite varias lecturas.':''} ${state.endings.length===15?'Archivo completo · Quince finales registrados.':''}</p><h2>Pistas reunidas</h2><div class="board">${state.clues.map(x=>`<div class="clue">${esc(x)}</div>`).join('')||'Aún no hay pistas.'}</div>`}
function historyPanel(){modal.hidden=false;modal.innerHTML=`<button class="close" onclick="window.closePanel()">Cerrar ✕</button><h2>Historial de lectura</h2>${state.history.slice(-35).map(x=>`<p><b>${esc(x[0])}</b> · ${esc(x[1])}</p>`).join('')||'<p>La historia acaba de comenzar.</p>'}`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
window.closePanel=()=>{modal.hidden=true};window.archive=archive;window.newRoute=()=>{modal.hidden=true;chapterTwo()};window.restart=()=>{if(confirm('¿Reiniciar el capítulo 1? El progreso de finales queda guardado.')){const endings=state.endings.slice(),ngp=state.ngp;Object.assign(state,{chapter:1,scene:0,path:'undecided',suspicion:ngp?8:12,police:38,devotion:18,fear:12,sanity:82,power:ngp?65:55,evidence:0,rel:{Iris:0,Nera:0,Vela:0,Ciro:0},flags:{face:false,real:false,witness:false,mistakes:0},name:'',cause:'',hour:'',clues:[],history:[],endings,ngp});modal.hidden=true;begin()}};
function save(show=true){try{localStorage.setItem('chronicleOfAshSave',JSON.stringify(state));if(show)notify('Partida guardada localmente.')}catch(e){if(show)notify('No se pudo guardar en este navegador.')}}
function load(){try{const s=JSON.parse(localStorage.getItem('chronicleOfAshSave')||'null');if(s&&s.endings)Object.assign(state,s)}catch(e){}}
function modalPanel(which){if(which==='meters'){modal.hidden=false;modal.innerHTML=`<button class="close" onclick="window.closePanel()">Cerrar ✕</button><h2>Estado · Relaciones y medidores</h2>${metrics()}`}else if(which==='board')board();else if(which==='notebook')notebook(false);else if(which==='history')historyPanel();else if(which==='save'){modal.hidden=false;modal.innerHTML=`<button class="close" onclick="window.closePanel()">Cerrar ✕</button><h2>Guardar / cargar</h2><p>El progreso se conserva localmente en este navegador.</p><button onclick="window.doSave()">Guardar ahora</button> <button onclick="window.doLoad()">Cargar partida</button> <button onclick="window.archive()">Abrir galería</button>`}}
window.doSave=()=>save();window.doLoad=()=>{load();modal.hidden=true;notify('Partida cargada. Pulsa continuar para seguir.')};document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>modalPanel(b.dataset.panel));$('#auto').onclick=()=>{state.auto=!state.auto;$('#auto').textContent=`Auto: ${state.auto?'sí':'no'}`;if(state.auto)autoTick()};function autoTick(){if(!state.auto)return;if(!choicesBox.hidden)return;$('#advance').click();setTimeout(autoTick,2600)}$('#skip').onclick=()=>{if(!choicesBox.hidden){notify('Elige una opción para continuar.');return}$('#advance').click()};$('#game')?.addEventListener('click',()=>{});$('#advance').addEventListener('click',()=>{const old=speaker.textContent;if(line.textContent)state.history.push([old,line.textContent])});
load();title();
})();

