7: const inc=(k,n)=>{state[k]+=n;clamp()},rel=(k,n)=>{state.rel[k]+=n},clue=s=>{if(!state.clues.includes(s))state.clues.push(s)};
8: function scene(bg,title='LA CIUDAD DE CENIZA',chapter='CAPÍTULO 1 · EL MARGEN DE LA NOCHE'){stage.style.backgroundImage=`url('${img.bg(bg)}')`;$('#scene-title').textContent=title;$('#chapter-label').textContent=chapter;portraitWrap.style.opacity='1';$('#cg')?.remove()}
9: function showCG(name){$('#cg')?.remove();const el=document.createElement('img');el.id='cg';el.className='cg';el.src=img.cg(name);stage.append(el)}
10: function say(who,text,person=null,expression='neutral',next=null){choicesBox.hidden=true;portraitWrap.style.display=person?'flex':'none';if(person){portrait.src=img.char(person,expression);portrait.alt=`${who}, expresión ${expression}`}speaker.textContent=who;line.textContent=text;$('#advance').style.display=next?'block':'none';$('#advance').onclick=()=>next&&next()}
