1: /* Chronicle of Ash — interactive, original visual novel. localStorage save; no external game engine required. */
2: (()=>{'use strict';
3: const $=s=>document.querySelector(s), stage=$('#stage'), line=$('#line'), speaker=$('#speaker'), portrait=$('#portrait'), portraitWrap=$('#portrait-wrap'), choicesBox=$('#choices'), modal=$('#modal'), toast=$('#toast');
4: const img={bg:n=>`assets/images/bg_${n}.png`,char:(n,e='neutral')=>`assets/images/${n}_${e}.png`,cg:n=>`assets/images/cg_${n}.png`};
5: const state={chapter:1,scene:0,path:'undecided',suspicion:12,police:38,devotion:18,fear:12,sanity:82,power:55,evidence:0,rel:{Iris:0,Nera:0,Vela:0,Ciro:0},flags:{face:false,real:false,witness:false,mistakes:0},name:'',cause:'',hour:'',clues:[],endings:[],history:[],ngp:false};
6: const clamp=()=>{for(const k of ['suspicion','police','devotion','fear','sanity','power'])state[k]=Math.max(0,Math.min(100,state[k]));state.evidence=Math.max(0,Math.min(10,state.evidence))};
7: const inc=(k,n)=>{state[k]+=n;clamp()},rel=(k,n)=>{state.rel[k]+=n},clue=s=>{if(!state.clues.includes(s))state.clues.push(s)};
8: function scene(bg,title='LA CIUDAD DE CENIZA',chapter='CAPÍTULO 1 · EL MARGEN DE LA NOCHE'){stage.style.backgroundImage=`url('${img.bg(bg)}')`;$('#scene-title').textContent=title;$('#chapter-label').textContent=chapter;portraitWrap.style.opacity='1';$('#cg')?.remove()}
9: function showCG(name){$('#cg')?.remove();const el=document.createElement('img');el.id='cg';el.className='cg';el.src=img.cg(name);stage.append(el)}
10: function say(who,text,person=null,expression='neutral',next=null){choicesBox.hidden=true;portraitWrap.style.display=person?'flex':'none';if(person){portrait.src=img.char(person,expression);portrait.alt=`${who}, expresión ${expression}`}speaker.textContent=who;line.textContent=text;$('#advance').style.display=next?'block':'none';$('#advance').onclick=()=>next&&next()}
11: function choose(items){$('#advance').style.display='none';choicesBox.innerHTML='';choicesBox.hidden=false;for(const [label,fn] of items){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{choicesBox.hidden=true;fn()};choicesBox.append(b)}}
12: function notify(text){toast.textContent=text;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2100)}
13: function sequence(arr,done){let i=0;const go=()=>{if(i>=arr.length){done?.();return}const s=arr[i++];if(s.cg)showCG(s.cg);if(s.bg)scene(s.bg,s.title,s.chapter);say(s.who,s.text,s.person,s.exp||'neutral',go)};go()}
14: function title(){scene('alley','CHRONICLE OF ASH','NOVELA VISUAL · MISTERIO SOBRENATURAL');portraitWrap.style.display='none';$('#advance').style.display='none';$('#speaker').textContent='';$('#line').textContent='';choicesBox.hidden=true;$('#cg')?.remove();const card=document.createElement('div');card.className='title-card';card.innerHTML='<div><p>UNA CIUDAD · QUINCE FINALES</p><h1>Chronicle<br>of Ash</h1><p>LA CIUDAD DE CENIZA</p><button>Comenzar historia</button></div>';stage.append(card);card.querySelector('button').onclick=()=>{card.remove();begin()}}
15: function begin(){state.scene=0;scene('alley');sequence([{cg:'discovery',who:'Narración',text:'La lluvia dejó el callejón sin testigos. Casi sin testigos.'},{who:'Noa Senda',person:'noa',exp:'tense',text:'No estaba aquí cuando salí de la universidad. Tiene mi nombre escrito en la tapa… aunque la letra no es mía.'},{who:'Narración',text:'El cuaderno negro está seco. En la primera hoja, una frase: «Lo que se entrega a la noche siempre cobra una respuesta».'},{who:'Noa Senda',person:'noa',exp:'suspicious',text:'¿Quién dejaría algo así en un callejón?'}],()=>choose([
16: ['Llevarlo a la comisaría y declarar dónde apareció',()=>{state.path='detective';inc('police',12);inc('suspicion',-5);rel('Ciro',1);clue('Cuaderno hallado en el callejón; origen incierto');apartment()}],
17: ['Guardarlo y estudiar primero las páginas',()=>{state.path='kira';inc('devotion',8);inc('sanity',-3);clue('Tapa sin huellas legibles bajo la lluvia');apartment()}],
18: ['No tocarlo; buscar cámaras y preguntar al quiosquero',()=>{state.path='ally';inc('evidence',1);inc('police',5);inc('suspicion',-3);state.flags.witness=true;clue('Un quiosquero vio una silueta dejar el cuaderno');apartment()}]
19: ]))}
20: function apartment(){scene('apartment');sequence([{who:'Nera',person:'nera',text:'Buenas. ¿Tienes una manzana? No, claro que no. La gente cree que los muertos necesitan modales.'},{who:'Noa Senda',person:'noa',exp:'surprise',text:'¿Quién eres? ¿Cómo has entrado?'},{who:'Nera',person:'nera',text:'Nera. Vigía de la última tinta. Y sí, ese cuaderno puede escribir una muerte. Nombre auténtico y rostro conocido. Nada de apodos.'},{who:'Narración',text:'Nera bosteza y se sienta en el suelo, como si anunciar lo imposible fuera una tarea doméstica.'}],()=>choose([
21: ['Pedir las reglas completas, sin aceptar nada',()=>{inc('sanity',4);rel('Nera',1);clue('Regla declarada: nombre auténtico + rostro reconocido');say('Nera','Causa y hora son opcionales; el efecto no puede superar lo posible. Un nombre equivocado no hace nada.','nera','neutral',broadcast)}],
22: ['Exigir que se marche y cerrar el cuaderno',()=>{inc('sanity',2);inc('power',-4);rel('Nera',-1);say('Nera','Qué falta de hospitalidad. Te lo explicaré desde el pasillo.','nera','suspicious',broadcast)}],
23: ['Preguntar qué gana ella',()=>{inc('suspicion',3);rel('Nera',2);say('Nera','Yo gano una manzana. La eternidad es larga y la fruta siempre está demasiado lejos.','nera','smile',broadcast)}]
24: ]))}
25: function broadcast(){scene('tv');sequence([{who:'Radio Ciudad',text:'La ciudad debate la muerte de tres criminales condenados. En redes, una firma anónima ya tiene nombre: Kira. La policía no confirma relación entre los casos.'},{who:'Narración',text:'El presentador no mostró imágenes explícitas; sí mostró portadas, horarios y el miedo creciendo en comentarios.'},{who:'Noa Senda',person:'noa',exp:'tense',text:'Si alguien usa el cuaderno, ¿la ciudad lo llamará justicia?'}],()=>choose([
26: ['La opinión pública no convierte sospechas en pruebas',()=>{inc('suspicion',-2);inc('police',4);clue('Las tres muertes compartían cobertura mediática, no causa confirmada');university()}],
27: ['La gente puede apoyar una idea y temer a quien la encarna',()=>{inc('devotion',6);inc('fear',3);rel('Vela',1);university()}],
